ON CONFLICT (id) DO UPDATE SET
  district = EXCLUDED.district,
  category = EXCLUDED.category,
  tier = EXCLUDED.tier,
  price = EXCLUDED.price,
  x = EXCLUDED.x,
  z = EXCLUDED.z,
  w = EXCLUDED.w,
  d = EXCLUDED.d,
